-- CHAMBA 060 — Security Hardening-- 1. Habilitar RLS en worker_profiles + políticas-- 2. Agregar FKs faltantes en job_assignments y jobs-- 3. Agregar UNIQUE(job_id, worker_id) en job_assignments-- 4. Eliminar GRANT anon en ensure_phone_auth_user-- 5. Agregar is_approved check en políticas admin-- 6. Agregar CHECK constraint en jobs.category-- 7. Agregar índice compuesto en job_assignmentsSET statement_timeout = '120s';-- ═══════════════════════════════════════════════════════════════-- 1. RLS en worker_profiles-- ═══════════════════════════════════════════════════════════════ALTER TABLE worker_profiles ENABLE ROW LEVEL SECURITY;-- Cualquier usuario autenticado puede ver perfiles de trabajadores aprobadosCREATE POLICY "worker_profiles: public read approved"  ON worker_profiles FOR SELECT  TO authenticated  USING (    EXISTS (      SELECT 1 FROM profiles p      WHERE p.id = worker_profiles.worker_id        AND p.role = 'worker'        AND p.is_approved = true    )  );-- El propio trabajador puede ver su perfil completoCREATE POLICY "worker_profiles: owner read own"  ON worker_profiles FOR SELECT  TO authenticated  USING (worker_id = auth.uid());-- El propio trabajador puede actualizar su perfilCREATE POLICY "worker_profiles: owner update own"  ON worker_profiles FOR UPDATE  TO authenticated  USING (worker_id = auth.uid())  WITH CHECK (worker_id = auth.uid());-- El propio trabajador puede insertar su perfilCREATE POLICY "worker_profiles: owner insert own"  ON worker_profiles FOR INSERT  TO authenticated  WITH CHECK (worker_id = auth.uid());-- Admin puede hacer todoCREATE POLICY "worker_profiles: admin all"  ON worker_profiles FOR ALL  TO authenticated  USING (    EXISTS (      SELECT 1 FROM profiles p      WHERE p.id = auth.uid()        AND p.role::text = 'admin'        AND p.is_approved = true    )  );-- ═══════════════════════════════════════════════════════════════-- 2. Foreign Keys faltantes-- ═══════════════════════════════════════════════════════════════-- job_assignments → jobsDO $$BEGIN  IF NOT EXISTS (    SELECT 1 FROM information_schema.table_constraints    WHERE constraint_name = 'fk_job_assignments_job'      AND table_name = 'job_assignments'  ) THEN    ALTER TABLE job_assignments      ADD CONSTRAINT fk_job_assignments_job      FOREIGN KEY (job_id) REFERENCES jobs(id) ON DELETE CASCADE;  END IF;END$$;-- job_assignments → profiles (worker)DO $$BEGIN  IF NOT EXISTS (    SELECT 1 FROM information_schema.table_constraints    WHERE constraint_name = 'fk_job_assignments_worker'      AND table_name = 'job_assignments'  ) THEN    ALTER TABLE job_assignments      ADD CONSTRAINT fk_job_assignments_worker      FOREIGN KEY (worker_id) REFERENCES profiles(id) ON DELETE CASCADE;  END IF;END$$;-- jobs → profiles (created_by)DO $$BEGIN  IF NOT EXISTS (    SELECT 1 FROM information_schema.table_constraints    WHERE constraint_name = 'fk_jobs_created_by'      AND table_name = 'jobs'  ) THEN    ALTER TABLE jobs      ADD CONSTRAINT fk_jobs_created_by      FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE CASCADE;  END IF;END$$;-- ═══════════════════════════════════════════════════════════════-- 3. UNIQUE constraint en job_assignments-- ═══════════════════════════════════════════════════════════════DO $$BEGIN  IF NOT EXISTS (    SELECT 1 FROM information_schema.table_constraints    WHERE constraint_name = 'uq_job_assignments_job_worker'      AND table_name = 'job_assignments'  ) THEN    ALTER TABLE job_assignments      ADD CONSTRAINT uq_job_assignments_job_worker      UNIQUE (job_id, worker_id);  END IF;END$$;-- ═══════════════════════════════════════════════════════════════-- 4. Eliminar GRANT anon en ensure_phone_auth_user-- ═══════════════════════════════════════════════════════════════REVOKE ALL ON FUNCTION ensure_phone_auth_user FROM anon;REVOKE ALL ON FUNCTION ensure_phone_auth_user FROM PUBLIC;-- Solo authenticated puede invocarloGRANT EXECUTE ON FUNCTION ensure_phone_auth_user TO authenticated;-- ═══════════════════════════════════════════════════════════════-- 5. Agregar is_approved check en políticas admin existentes--    (actualizar políticas que solo verifican role = 'admin')-- ═══════════════════════════════════════════════════════════════-- precios_catalogo: admin writeDROP POLICY IF EXISTS "precios: admin write" ON precios_catalogo;CREATE POLICY "precios: admin write" ON precios_catalogo  FOR ALL  TO authenticated  USING (    EXISTS (      SELECT 1 FROM profiles p      WHERE p.id = auth.uid()        AND p.role::text = 'admin'        AND p.is_approved = true    )  )  WITH CHECK (    EXISTS (      SELECT 1 FROM profiles p      WHERE p.id = auth.uid()        AND p.role::text = 'admin'        AND p.is_approved = true    )  );-- service_categories: admin allDROP POLICY IF EXISTS "catalog: admin all" ON service_categories;CREATE POLICY "catalog: admin all" ON service_categories  FOR ALL  TO authenticated  USING (    EXISTS (      SELECT 1 FROM profiles p      WHERE p.id = auth.uid()        AND p.role::text = 'admin'        AND p.is_approved = true    )  )  WITH CHECK (    EXISTS (      SELECT 1 FROM profiles p      WHERE p.id = auth.uid()        AND p.role::text = 'admin'        AND p.is_approved = true    )  );-- service_types: admin allDROP POLICY IF EXISTS "service_types: admin all" ON service_types;CREATE POLICY "service_types: admin all" ON service_types  FOR ALL  TO authenticated  USING (    EXISTS (      SELECT 1 FROM profiles p      WHERE p.id = auth.uid()        AND p.role::text = 'admin'        AND p.is_approved = true    )  )  WITH CHECK (    EXISTS (      SELECT 1 FROM profiles p      WHERE p.id = auth.uid()        AND p.role::text = 'admin'        AND p.is_approved = true    )  );-- ═══════════════════════════════════════════════════════════════-- 6. CHECK constraint en jobs.category (validar slugs conocidos)-- ═══════════════════════════════════════════════════════════════DO $$BEGIN  IF NOT EXISTS (    SELECT 1 FROM information_schema.check_constraints    WHERE constraint_name = 'chk_jobs_category'      AND table_name = 'jobs'  ) THEN    ALTER TABLE jobs      ADD CONSTRAINT chk_jobs_category      CHECK (category IS NULL OR length(trim(category)) > 0);  END IF;END$$;-- ═══════════════════════════════════════════════════════════════-- 7. Índice compuesto para count_worker_active_commitments-- ═══════════════════════════════════════════════════════════════CREATE INDEX IF NOT EXISTS idx_ja_worker_selection  ON job_assignments (worker_id, selection_status);